result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/migrations/001_create_notes.sql", "content": "-- create notes table
CREATE TABLE notes (
    id          INTEGER PRIMARY KEY,
    title       TEXT NOT NULL,
    body        TEXT NOT NULL DEFAULT '',
    created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE UNIQUE INDEX idx_notes_title ON notes(title);
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/migrations/002_add_priority.down.sql", "content": "-- remove priority column added in the up section
DROP INDEX IF EXISTS idx_notes_title;
ALTER TABLE notes DROP COLUMN priority;
CREATE UNIQUE INDEX idx_notes_title ON notes(title);
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/migrations/002_add_priority.sql", "content": "-- add priority column and backfill from body content
ALTER TABLE notes ADD COLUMN priority INTEGER NOT NULL DEFAULT 0;

UPDATE notes SET priority = 2 WHERE lower(body) LIKE '%urgent%';
UPDATE notes SET priority = 1 WHERE priority = 0 AND length(body) > 0;
"})
print(result)
